export function setupExtraction({getSources,getCurrent,isBusy,upload,create,strokes,notify}) {
  const chosen=new Set();let draft=[],sources=[],renderQueue=Promise.resolve();
  const dialog=document.createElement('dialog');dialog.className='extract-dialog';
  dialog.innerHTML=`<div class="extract-heading"><div><span class="eyebrow">EXTRACT & MERGE</span><h2>페이지 추출·병합</h2></div><button class="extract-close" aria-label="닫기">✕</button></div><section class="extract-source"><div class="extract-section-title"><div><h3>1. 원본에서 페이지 선택</h3><p>여러 페이지를 체크한 뒤, 선택한 페이지 중 하나를 아래 작업 창으로 드래그하세요.</p></div><label class="upload">＋ 원본 PDF 추가<input class="extract-files" type="file" accept=".pdf,application/pdf" multiple hidden></label></div><div class="extract-select-bar"><label><input class="extract-all" type="checkbox"> 전체 선택</label><span class="extract-selection-count"></span><button class="extract-add">선택 페이지 가져오기 ↓</button></div><div class="extract-sources"></div></section><section class="extract-work"><div class="extract-section-title"><div><h3>2. 새 문서 작업 창 <span class="extract-draft-count"></span></h3><p>드래그하여 순서를 바꾸세요. 같은 페이지를 여러 번 가져올 수도 있습니다.</p></div><button class="extract-clear">작업 창 비우기</button></div><div class="extract-drop" tabindex="0" aria-label="새 문서 페이지 작업 창"></div></section><div class="extract-footer"><label>새 문서 이름 <input class="extract-name" value="추출_병합_문서" maxlength="100"></label><span>원본 파일은 변경되지 않습니다.</span><button class="primary extract-create">새 문서 만들기 →</button></div>`;
  document.body.append(dialog);const $=s=>dialog.querySelector(s);
  function clone(p){return {...p,id:crypto.randomUUID(),selected:false,strokes:structuredClone(p.strokes)}}
  function counts(){const n=sources.filter(p=>chosen.has(p.id)).length;$('.extract-selection-count').textContent=`${n}개 선택`;
    $('.extract-all').checked=!!sources.length&&n===sources.length;$('.extract-all').indeterminate=n>0&&n<sources.length;
    $('.extract-add').disabled=!n;$('.extract-draft-count').textContent=`${draft.length}페이지`;$('.extract-create').disabled=!draft.length;$('.extract-clear').disabled=!draft.length;
  }
  function thumbnail(p,canvas){renderQueue=renderQueue.catch(()=>{}).then(async()=>{if(!canvas.isConnected)return;try{const pg=await p.doc.getPage(p.index),base=pg.getViewport({scale:1,rotation:p.rotation}),vp=pg.getViewport({scale:Math.min(200/base.width,230/base.height),rotation:p.rotation});canvas.width=vp.width;canvas.height=vp.height;await pg.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;const ink=document.createElement('canvas');ink.width=canvas.width;ink.height=canvas.height;strokes(ink.getContext('2d'),p,canvas.width,canvas.height);canvas.getContext('2d').drawImage(ink,0,0)}catch{canvas.parentElement.classList.add('preview-error');canvas.setAttribute('aria-label','미리보기를 표시할 수 없습니다.')}})}
  function refreshChecks(){dialog.querySelectorAll('[data-source-id]').forEach(card=>{const yes=chosen.has(card.dataset.sourceId);card.classList.toggle('picked',yes);card.querySelector('input').checked=yes});counts()}
  function renderSources(){sources=getSources();const host=$('.extract-sources');host.replaceChildren();const groups=new Map();for(const p of sources){if(!groups.has(p.doc))groups.set(p.doc,[]);groups.get(p.doc).push(p)}
    for(const group of groups.values()){const section=document.createElement('div');section.className='extract-file';const title=document.createElement('h4');title.textContent=`${group[0].name} · ${group.length}페이지`;section.append(title);const grid=document.createElement('div');grid.className='extract-grid';section.append(grid);host.append(section);
      for(const p of group){const card=document.createElement('div');card.className='extract-card';card.dataset.sourceId=p.id;card.draggable=true;card.tabIndex=0;card.innerHTML='<label><input type="checkbox"><span></span></label><canvas></canvas>';card.querySelector('span').textContent=`${p.index}페이지`;card.querySelector('input').setAttribute('aria-label',`${p.name} ${p.index}페이지 선택`);function toggle(){chosen.has(p.id)?chosen.delete(p.id):chosen.add(p.id);refreshChecks()}card.onclick=e=>{if(e.target.tagName==='LABEL'||e.target.tagName==='SPAN'){e.preventDefault()}toggle()};card.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();toggle()}};card.ondragstart=e=>{if(!chosen.has(p.id)){chosen.clear();chosen.add(p.id);refreshChecks()}e.dataTransfer.effectAllowed='copy';e.dataTransfer.setData('application/x-moa-source',JSON.stringify(sources.filter(x=>chosen.has(x.id)).map(x=>x.id)));e.dataTransfer.setData('text/plain',`${chosen.size}개 PDF 페이지`)};grid.append(card);thumbnail(p,card.querySelector('canvas'))}
    }if(!sources.length){const p=document.createElement('p');p.textContent='원본 PDF를 추가하면 페이지 미리보기가 여기에 표시됩니다.';host.append(p)}refreshChecks();
  }
  function importSelected(ids,at=draft.length){const wanted=new Set(ids),items=sources.filter(p=>wanted.has(p.id)).map(clone);draft.splice(at,0,...items);renderDraft();if(items.length)notify(`${items.length}개 페이지를 작업 창으로 가져왔습니다.`)}
  function handleDrop(e,at){e.preventDefault();e.stopPropagation();$('.extract-drop').classList.remove('drag-over');const incoming=e.dataTransfer.getData('application/x-moa-source'),moving=e.dataTransfer.getData('application/x-moa-draft');if(incoming){try{const ids=JSON.parse(incoming);if(Array.isArray(ids))importSelected(ids,at)}catch{}return}if(moving){const from=draft.findIndex(p=>p.id===moving);if(from<0)return;const [p]=draft.splice(from,1);draft.splice(at>from?at-1:at,0,p);renderDraft()}}
  function renderDraft(){const host=$('.extract-drop');host.replaceChildren();if(!draft.length){const empty=document.createElement('div');empty.className='extract-drop-empty';empty.innerHTML='<b>＋</b><strong>선택한 페이지를 이곳에 놓으세요</strong><span>위쪽 원본에서 필요한 페이지만 가져와 새 문서를 만듭니다.</span>';host.append(empty)}
    draft.forEach((p,i)=>{const card=document.createElement('div');card.className='extract-card draft-card';card.draggable=true;card.innerHTML='<div class="draft-card-top"><strong></strong><button aria-label="작업 창에서 제외">×</button></div><canvas></canvas><small></small><div class="draft-arrows"><button aria-label="앞으로 이동">←</button><button aria-label="뒤로 이동">→</button></div>';card.querySelector('strong').textContent=`${i+1}`;card.querySelector('small').textContent=`${p.name} · ${p.index}p`;card.querySelector('small').title=`${p.name} · ${p.index}페이지`;const buttons=card.querySelectorAll('button');buttons[0].onclick=()=>{draft.splice(i,1);renderDraft()};[buttons[1],buttons[2]].forEach((b,k)=>{const to=i+(k?1:-1);b.disabled=to<0||to>=draft.length;b.onclick=()=>{[draft[i],draft[to]]=[draft[to],draft[i]];renderDraft()}});card.ondragstart=e=>{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('application/x-moa-draft',p.id);e.dataTransfer.setData('text/plain','작업 페이지 순서 변경')};card.ondragover=e=>{e.preventDefault();e.stopPropagation();card.classList.add('drop-before')};card.ondragleave=()=>card.classList.remove('drop-before');card.ondrop=e=>handleDrop(e,i);host.append(card);thumbnail(p,card.querySelector('canvas'))});counts();
  }
  const drop=$('.extract-drop');drop.ondragover=e=>{if([...e.dataTransfer.types].some(t=>t==='application/x-moa-source'||t==='application/x-moa-draft')){e.preventDefault();e.stopPropagation();drop.classList.add('drag-over')}};drop.ondragleave=e=>{if(!drop.contains(e.relatedTarget))drop.classList.remove('drag-over')};drop.ondrop=e=>handleDrop(e,draft.length);
  $('.extract-all').onchange=e=>{sources.forEach(p=>e.target.checked?chosen.add(p.id):chosen.delete(p.id));refreshChecks()};$('.extract-add').onclick=()=>importSelected([...chosen]);$('.extract-clear').onclick=()=>{draft=[];renderDraft()};$('.extract-close').onclick=()=>dialog.close();$('.extract-files').onchange=async e=>{await upload(e.target.files);e.target.value='';renderSources()};$('.extract-create').onclick=()=>{if(isBusy())return notify('PDF를 불러온 뒤 새 문서를 만들어 주세요.');if(!draft.length)return;const name=($('.extract-name').value.trim()||'추출_병합_문서').replace(/\.pdf$/i,'')+'.pdf';create(draft.map(clone),name);dialog.close();notify(`${draft.length}페이지의 새 문서를 만들었습니다. PDF 다운로드로 저장하세요.`)};
  return {open(){if(isBusy())return notify('현재 작업이 끝난 후 열어 주세요.');getCurrent().forEach(p=>{if(p.selected)chosen.add(p.id)});dialog.showModal();renderSources();renderDraft()}};
}
